#include <stdexcept>
#include <string>

std::string slice(const std::string& s, std::size_t pos, std::size_t count = std::string::npos)
{
    if (pos > s.size()) throw std::out_of_range("slice: pos is past the end");
    const std::size_t n{ count < s.size() - pos ? count : s.size() - pos };
    return s.substr(pos, n);
}

std::string lastChars(const std::string& s, std::size_t count)
{
    if (count >= s.size()) return s;
    return s.substr(s.size() - count);
}

unitTests:
TEST("slicing inside the string") {
    CHECK_EQ(slice("documentation", 0, 3), std::string("doc"));
    CHECK_EQ(slice("documentation", 3, 5), std::string("ument"));
    CHECK_EQ(slice("documentation", 9), std::string("tion"));
}
TEST("counts that run past the end") {
    CHECK_EQ(slice("abc", 1, 100), std::string("bc"));
    CHECK_EQ(slice("abc", 0, std::string::npos), std::string("abc"));
}
TEST("the end itself and beyond") {
    CHECK_EQ(slice("abc", 3), std::string(""));
    CHECK_EQ(slice("", 0), std::string(""));
    CHECK_THROWS_AS(slice("abc", 4), std::out_of_range);
    CHECK_THROWS_AS(slice("", 1, 0), std::out_of_range);
}
TEST("the last characters") {
    CHECK_EQ(lastChars("reference", 4), std::string("ence"));
    CHECK_EQ(lastChars("reference", 9), std::string("reference"));
    CHECK_EQ(lastChars("reference", 50), std::string("reference"));
    CHECK_EQ(lastChars("reference", 0), std::string(""));
    CHECK_EQ(lastChars("", 3), std::string(""));
}

